var pname = Tama.Args.Get(args, "param", "");
var plots = (IDictionary<string,object>)args["plots"];
var inv = doc.ActiveProjectLocation.GetTotalTransform().Inverse;
Func<XYZ,double[]> sh = p => { var s = inv.OfPoint(p); return new[]{ s.X*0.3048, s.Y*0.3048 }; };
var floors = new FilteredElementCollector(doc).OfClass(typeof(Floor)).Cast<Floor>().ToList();
var setbacks = new FilteredElementCollector(doc).OfClass(typeof(CurveElement)).Cast<CurveElement>().Where(c => c.CurveElementType == CurveElementType.ModelCurve && c.LineStyle != null && c.LineStyle.Name.Contains("Setback")).ToList();
Func<List<double[]>, double, double, bool> inside = (poly, x, y) => { bool r = false; for (int i=0,j=poly.Count-1;i<poly.Count;j=i++) { if (((poly[i][1]>y)!=(poly[j][1]>y)) && (x < (poly[j][0]-poly[i][0])*(y-poly[i][1])/(poly[j][1]-poly[i][1])+poly[i][0])) r = !r; } return r; };
var outp = new List<object>();
foreach (var kv in plots) {
  var id = kv.Key;
  var tg = ((object[])kv.Value).Select(o => { var a = (object[])o; return new[]{ Convert.ToDouble(a[0]), Convert.ToDouble(a[1]) }; }).ToList();
  var hits = floors.Where(f => { var p = f.LookupParameter(pname); var v = p?.AsString() ?? p?.AsValueString(); return v != null && v.Trim().EndsWith(id); }).ToList();
  var fl = new List<object>();
  foreach (var f in hits) {
    var sk = doc.GetElement(f.SketchId) as Sketch;
    var verts = new List<double[]>(); var types = new List<string>(); int loopsN = 0;
    foreach (CurveArray ca in sk.Profile) { loopsN++; if (loopsN > 1) continue; foreach (Curve c in ca) { verts.Add(sh(c.GetEndPoint(0))); types.Add(c is Arc ? "A" : "L"); } }
    var match = tg.Select((t,i) => { var b = verts.OrderBy(v => Math.Pow(v[0]-t[0],2)+Math.Pow(v[1]-t[1],2)).First(); return new { pt = "P0"+(i+1), dmm = Math.Round(Math.Sqrt(Math.Pow(b[0]-t[0],2)+Math.Pow(b[1]-t[1],2))*1000,1) }; }).ToList();
    var lines = setbacks.Where(c => { var m = sh(c.GeometryCurve.Evaluate(0.5,true)); return inside(verts, m[0], m[1]); }).Select(c => c.Id.IntegerValue).ToList();
    fl.Add(new { floorId = f.Id.IntegerValue, value = f.LookupParameter(pname)?.AsString(), type = f.Name, workset = doc.GetWorksetTable().GetWorkset(f.WorksetId).Name, owner = WorksharingUtils.GetWorksharingTooltipInfo(doc, f.Id).Owner, loops = loopsN, edges = string.Join("", types), vertexCount = verts.Count, cornerDiff_mm = match, setbackLineIds = lines });
  }
  outp.Add(new { plot = id, floorsFound = hits.Count, floors = fl });
}
return new { activeView = doc.ActiveView.Name, plots = outp };
